import{_ as r,o as a,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Scientific Users Working Group BoF - Moderated by Dan van der Ster, Clyso","description":"","frontmatter":{"title":"Ceph Scientific Users Working Group BoF - Moderated by Dan van der Ster, Clyso","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph社区","分布式存储","存储优化","科学研究","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Scientific_Users_Working_Group_BoF_-_Moderated_by_Dan_van_der_Ster_Clyso.md","filePath":"posts/2025/Ceph_Scientific_Users_Working_Group_BoF_-_Moderated_by_Dan_van_der_Ster_Clyso.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Ceph_Scientific_Users_Working_Group_BoF_-_Moderated_by_Dan_van_der_Ster_Clyso.md"};function n(l,e,s,h,_,d){return a(),o("div",null,[...e[0]||(e[0]=[t('<h3 id="ceph-科学用户工作组-bof-会议纪要" tabindex="-1">Ceph 科学用户工作组 BoF 会议纪要 <a class="header-anchor" href="#ceph-科学用户工作组-bof-会议纪要" aria-label="Permalink to &quot;Ceph 科学用户工作组 BoF 会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>会议名称</strong>: Ceph 科学用户组（鸟群聚会）</li><li><strong>时间</strong>: 2023年10月（具体日期未明确）</li><li><strong>地点</strong>: 温哥华（线下）</li><li><strong>主持人</strong>: Kevin</li><li><strong>核心组织者</strong>: Kevin、Mataya（ETH Zurich）、Tom（SDFC）、Enrico（CERN）</li><li><strong>会议形式</strong>: 非正式讨论（鸟群聚会）</li></ul><h4 id="会议关键讨论内容" tabindex="-1">会议关键讨论内容 <a class="header-anchor" href="#会议关键讨论内容" aria-label="Permalink to &quot;会议关键讨论内容&quot;">​</a></h4><h4 id="_1-参会者自我介绍" tabindex="-1">1. 参会者自我介绍 <a class="header-anchor" href="#_1-参会者自我介绍" aria-label="Permalink to &quot;1. 参会者自我介绍&quot;">​</a></h4><ul><li><strong>Kevin</strong>: Ceph社区科学用户组的发起人，组织每两个月一次的虚拟会议。</li><li><strong>Mataya</strong>: ETH Zurich，专注于私有云场景下的Ceph部署，支持HPC和Batch系统。</li><li><strong>Tom</strong>: 英国科研机构SDFC，管理大规模Ceph集群，支持通用存储用例。</li><li><strong>Enrico</strong>: CERN，管理Ceph集群支持OpenStack和容器存储，未用于物理实验数据。</li><li><strong>其他参与者</strong>: Jeff Albert（University Victoria）、Gregori（Elettra同步辐射实验室）、Torson（University of Bremen）等。</li></ul><h4 id="_2-主要议题" tabindex="-1">2. 主要议题 <a class="header-anchor" href="#_2-主要议题" aria-label="Permalink to &quot;2. 主要议题&quot;">​</a></h4><h5 id="_1-旧硬件的再利用与生命周期管理" tabindex="-1">(1) 旧硬件的再利用与生命周期管理 <a class="header-anchor" href="#_1-旧硬件的再利用与生命周期管理" aria-label="Permalink to &quot;(1) 旧硬件的再利用与生命周期管理&quot;">​</a></h5><ul><li><strong>挑战</strong>: 硬件保修到期后可靠性下降，容量规划困难。</li><li><strong>解决方案</strong>: 将过保硬件用于非关键负载、逐步淘汰老旧服务器、保留过保硬件作为备件。</li></ul><h5 id="_2-ceph在科学场景中的扩展挑战" tabindex="-1">(2) Ceph在科学场景中的扩展挑战 <a class="header-anchor" href="#_2-ceph在科学场景中的扩展挑战" aria-label="Permalink to &quot;(2) Ceph在科学场景中的扩展挑战&quot;">​</a></h5><ul><li><strong>未充分覆盖的用例</strong>: 企业级虚拟化存储、HPC高性能存储、教育与推广。</li><li><strong>潜在方向</strong>: 通过试点验证CephFS性能、推动开源存储替代商业方案。</li></ul><h5 id="_3-ceph与磁带库的集成" tabindex="-1">(3) Ceph与磁带库的集成 <a class="header-anchor" href="#_3-ceph与磁带库的集成" aria-label="Permalink to &quot;(3) Ceph与磁带库的集成&quot;">​</a></h5><ul><li><strong>现状</strong>: CERN使用自有磁带库，IBM方案通过RGW将数据推送至磁带。</li><li><strong>讨论共识</strong>: 磁带是长期归档的最佳选择，Ceph可作为热存储层。</li></ul><h5 id="_4-社区贡献与ceph基金会合作" tabindex="-1">(4) 社区贡献与Ceph基金会合作 <a class="header-anchor" href="#_4-社区贡献与ceph基金会合作" aria-label="Permalink to &quot;(4) 社区贡献与Ceph基金会合作&quot;">​</a></h5><ul><li><strong>当前贡献形式</strong>: 技术预览反馈、文档补充、构建包维护。</li><li><strong>未来建议</strong>: 更多机构加入Ceph基金会、组织地区性活动。</li></ul><h4 id="行动计划与决议" tabindex="-1">行动计划与决议 <a class="header-anchor" href="#行动计划与决议" aria-label="Permalink to &quot;行动计划与决议&quot;">​</a></h4><ol><li><strong>旧硬件管理</strong>: 探索将过保硬件用于独立故障域、制定硬件淘汰标准。</li><li><strong>性能优化</strong>: 推动CephFS在HPC场景的基准测试。</li><li><strong>归档集成</strong>: 评估IBM RGW到磁带的方案。</li><li><strong>社区协作</strong>: 下次虚拟会议将于11月25日举行，议题征集通过邮件列表通知。</li></ol><h4 id="关键词保留" tabindex="-1">关键词保留 <a class="header-anchor" href="#关键词保留" aria-label="Permalink to &quot;关键词保留&quot;">​</a></h4><ul><li><strong>Ceph组件</strong>: OSD、MON、MDS、PG、RADOS、RGW、CephFS、RBD、librados.</li><li><strong>技术概念</strong>: CRUSH算法、高可用性（HA）、副本（Replication）、纠删码（Erasure Coding）、BlueStore、性能调优（Performance Tuning）.</li><li><strong>生态集成</strong>: Kubernetes、OpenStack、AWS S3、磁带归档（Tape Library）.</li></ul>',19)])])}const p=r(i,[["render",n]]);export{g as __pageData,p as default};
